{"command":"cat << 'EOF' > config.go
package main

import (
	"bufio"
	"fmt"
	"os"
	"os/exec"
	"path/filepath"
	"regexp"
	"strings"
	"time"
)

type Config struct {
	ConfigDir      string
	DataDir        string
	CacheDir       string
	SelfPath       string
	BashPath       string
	DisableStdin   bool
	LoadDotenv     bool
	StrictEnv      bool
	WarnTimeout    time.Duration
	HideEnvDiff    bool
	LogFormat      string
	LogFilter      *regexp.Regexp
	WhitelistPrefix []string
	WhitelistExact  map[string]bool
}

func LoadConfig(env map[string]string) (*Config, error) {
	selfPath, err := os.Executable()
	if err != nil {
		selfPath = "/workspace/executable"
	}
	selfPath, _ = filepath.EvalSymlinks(selfPath)

	home := env["HOME"]
	if home == "" {
		home = "/home/agent"
	}

	xdgConfig := env["XDG_CONFIG_HOME"]
	if xdgConfig == "" {
		xdgConfig = filepath.Join(home, ".config")
	}

	xdgData := env["XDG_DATA_HOME"]
	if xdgData == "" {
		xdgData = filepath.Join(home, ".local", "share")
	}

	xdgCache := env["XDG_CACHE_HOME"]
	if xdgCache == "" {
		xdgCache = filepath.Join(home, ".cache")
	}

	configDir := env["DIRENV_CONFIG"]
	if configDir == "" {
		configDir = filepath.Join(xdgConfig, "direnv")
	}

	dataDir := filepath.Join(xdgData, "direnv")
	cacheDir := filepath.Join(xdgCache, "direnv")

	cfg := &Config{
		ConfigDir:      configDir,
		DataDir:        dataDir,
		CacheDir:       cacheDir,
		SelfPath:       selfPath,
		WarnTimeout:    5 * time.Second,
		LogFormat:      "\x1b[0mdirenv: %s",
		WhitelistExact: make(map[string]bool),
	}

	// Parse direnv.toml or config.toml
	tomlPath := filepath.Join(configDir, "direnv.toml")
	if _, err := os.Stat(tomlPath); os.IsNotExist(err) {
		tomlPath = filepath.Join(configDir, "config.toml")
	}

	if data, err := os.ReadFile(tomlPath); err == nil {
		parseTOML(string(data), cfg, home)
	}

	// Environment variable overrides
	if bash := env["DIRENV_BASH"]; bash != "" {
		cfg.BashPath = bash
	}
	if cfg.BashPath == "" {
		if path, err := exec.LookPath("bash"); err == nil {
			cfg.BashPath = path
		} else {
			cfg.BashPath = "/bin/bash"
		}
	}

	if wt := env["DIRENV_WARN_TIMEOUT"]; wt != "" {
		if d, err := time.ParseDuration(wt); err == nil {
			cfg.WarnTimeout = d
		}
	}

	if lf := env["DIRENV_LOG_FORMAT"]; lf != "" {
		cfg.LogFormat = lf
	}

	return cfg, nil
}

func parseTOML(content string, cfg *Config, home string) {
	scanner := bufio.NewScanner(strings.NewReader(content))
	currentSection := ""

	for scanner.Scan() {
		line := strings.TrimSpace(scanner.Text())
		if line == "" || strings.HasPrefix(line, "#") {
			continue
		}

		if strings.HasPrefix(line, "[") && strings.HasSuffix(line, "]") {
			currentSection = strings.ToLower(strings.TrimSpace(line[1 : len(line)-1]))
			continue
		}

		parts := strings.SplitN(line, "=", 2)
		if len(parts) != 2 {
			continue
		}
		key := strings.ToLower(strings.TrimSpace(parts[0]))
		val := strings.TrimSpace(parts[1])

		// Strip trailing comments
		if idx := strings.Index(val, "#"); idx != -1 {
			// Make sure # is not in quotes
			if !inQuotes(val[:idx]) {
				val = strings.TrimSpace(val[:idx])
			}
		}

		switch currentSection {
		case "global":
			switch key {
			case "bash_path":
				cfg.BashPath = unquote(val)
			case "disable_stdin":
				cfg.DisableStdin = parseBool(val)
			case "load_dotenv":
				cfg.LoadDotenv = parseBool(val)
			case "strict_env":
				cfg.StrictEnv = parseBool(val)
			case "warn_timeout":
				if d, err := time.ParseDuration(unquote(val)); err == nil {
					cfg.WarnTimeout = d
				}
			case "hide_env_diff":
				cfg.HideEnvDiff = parseBool(val)
			case "log_format":
				cfg.LogFormat = unquote(val)
			case "log_filter":
				pattern := unquote(val)
				if pattern != "" {
					if re, err := regexp.Compile(pattern); err == nil {
						cfg.LogFilter = re
					}
				}
			}
		case "whitelist":
			switch key {
			case "prefix":
				arr := parseStringArray(val, home)
				cfg.WhitelistPrefix = append(cfg.WhitelistPrefix, arr...)
			case "exact":
				arr := parseStringArray(val, home)
				for _, item := range arr {
					if !strings.HasSuffix(item, "/.envrc") && !strings.HasSuffix(item, "/.env") {
						item = filepath.Join(item, ".envrc")
					}
					cfg.WhitelistExact[item] = true
				}
			}
		}
	}
}

func parseBool(val string) bool {
	val = strings.ToLower(strings.TrimSpace(val))
	return val == "true" || val == "1" || val == "yes"
}

func unquote(val string) string {
	val = strings.TrimSpace(val)
	if (strings.HasPrefix(val, "\"") && strings.HasSuffix(val, "\"")) ||
		(strings.HasPrefix(val, "'") && strings.HasSuffix(val, "'")) {
		return val[1 : len(val)-1]
	}
	return val
}

func inQuotes(s string) bool {
	qCount := 0
	for _, c := range s {
		if c == '"' || c == '\'' {
			qCount++
		}
	}
	return qCount%2 != 0
}

func parseStringArray(val string, home string) []string {
	val = strings.TrimSpace(val)
	if strings.HasPrefix(val, "[") && strings.HasSuffix(val, "]") {
		val = val[1 : len(val)-1]
	}
	items := strings.Split(val, ",")
	var result []string
	for _, item := range items {
		item = unquote(strings.TrimSpace(item))
		if item != "" {
			if strings.HasPrefix(item, "~/") {
				item = filepath.Join(home, item[2:])
			}
			result = append(result, filepath.Clean(item))
		}
	}
	return result
}

func (cfg *Config) Log(msg string) {
	if cfg.LogFormat == "-" {
		return
	}
	if cfg.LogFilter != nil && cfg.LogFilter.MatchString(msg) {
		return
	}
	formatted := msg
	if strings.Contains(cfg.LogFormat, "%s") {
		formatted = fmt.Sprintf(cfg.LogFormat, msg)
	}
	fmt.Fprintln(os.Stderr, formatted)
}

func (cfg *Config) LogError(msg string) {
	formatted := fmt.Sprintf("\x1b[31mdirenv: %s\x1b[0m", msg)
	fmt.Fprintln(os.Stderr, formatted)
}
EOF"}

