package main

import (
	"bytes"
	"compress/zlib"
	"crypto/rand"
	"encoding/base64"
	"encoding/hex"
	"encoding/json"
	"fmt"
	"sort"
	"strings"
)

type Env map[string]string

func GetEnviron() Env {
	env := make(Env)
	for _, item := range osEnviron() {
		parts := strings.SplitN(item, "=", 2)
		if len(parts) == 2 {
			env[parts[0]] = parts[1]
		}
	}
	return env
}

var osEnviron = func() []string {
	return osEnvironReal()
}

func (e Env) Copy() Env {
	cp := make(Env, len(e))
	for k, v := range e {
		cp[k] = v
	}
	return cp
}

func (e Env) ToArray() []string {
	res := make([]string, 0, len(e))
	for k, v := range e {
		res = append(res, k+"="+v)
	}
	return res
}

type EnvDiff struct {
	Prev map[string]*string `json:"p"`
	Next map[string]string  `json:"n"`
