package main

import (
	"bytes"
	"compress/zlib"
	"encoding/base64"
	"encoding/json"
	"os"
	"path/filepath"
	"strings"
)

type WatchItem struct {
	Path    string `json:"path"`
	ModTime int64  `json:"modtime"`
	Exists  bool   `json:"exists"`
}

type WatchList []WatchItem

func NewWatchList() WatchList {
	return WatchList{}
}

func (w WatchList) Add(path string) WatchList {
	absPath, err := filepath.Abs(path)
	if err != nil {
		absPath = path
	}

	info, err := os.Stat(absPath)
	exists := !os.IsNotExist(err)
	var mtime int64
	if exists && info != nil {
		mtime = info.ModTime().Unix()
	}

	for i, item := range w {
		if item.Path == absPath {
			w[i].ModTime = mtime
			w[i].Exists = exists
			return w
		}
	}

	return append(w, WatchItem{
		Path:    absPath,
		ModTime: mtime,
		Exists:  exists,
	})
}

func (w WatchList) AddDir(dir string) (WatchList, error) {
	absDir, err := filepath.Abs(dir)
	if err != nil {
		absDir = dir
	}

	res := w.Add(absDir)

	err = filepath.Walk(absDir, func(path string, info os.FileInfo, err error) error {
		if err != nil {
			return nil
		}
		if path != absDir {
			res = res.Add(path)
		}
		return nil
	})

	return res, err
}

