		return "", err
	}
	if err := zw.Close(); err != nil {
		return "", err
	}
	return base64.URLEncoding.EncodeToString(buf.Bytes()), nil
}

func ParseWatchList(str string) (WatchList, error) {
	if str == "" {
		return WatchList{}, nil
	}
	if m := len(str) % 4; m != 0 {
		str += strings.Repeat("=", 4-m)
	}
	raw, err := base64.URLEncoding.DecodeString(str)
	if err != nil {
		raw, err = base64.StdEncoding.DecodeString(str)
		if err != nil {
			return nil, err
		}
	}
	zr, err := zlib.NewReader(bytes.NewReader(raw))
	if err != nil {
		return nil, err
	}
	defer zr.Close()

	var list WatchList
	if err := json.NewDecoder(zr).Decode(&list); err != nil {
		return nil, err
	}
	return list, nil
}

func (w WatchList) IsCurrent() (bool, string) {
	for _, item := range w {
		info, err := os.Stat(item.Path)
		exists := !os.IsNotExist(err)
		if exists != item.Exists {
