)

type AllowedStatus int

const (
	ALLOWED     AllowedStatus = 0
	NOT_ALLOWED AllowedStatus = 1
	DENIED      AllowedStatus = 2
)

type RC struct {
	Path    string
	Dir     string
	IsEnv   bool
	Content string
}

func FindRC(dir string, cfg *Config) *RC {
	curr := filepath.Clean(dir)

	for {
		envrcPath := filepath.Join(curr, ".envrc")
		if info, err := os.Stat(envrcPath); err == nil && !info.IsDir() {
			content, _ := os.ReadFile(envrcPath)
			return &RC{
				Path:    envrcPath,
				Dir:     curr,
				IsEnv:   false,
				Content: string(content),
			}
		}

		if cfg.LoadDotenv {
			envPath := filepath.Join(curr, ".env")
			if info, err := os.Stat(envPath); err == nil && !info.IsDir() {
				content, _ := os.ReadFile(envPath)
				return &RC{
					Path:    envPath,
					Dir:     curr,
					IsEnv:   true,
					Content: string(content),
				}
			}
		}

		parent := filepath.Dir(curr)
		if parent == curr {
			break
		}
		curr = parent
	}

	return nil
}

