	absPath, err := filepath.Abs(path)
	if err != nil {
		return nil, err
	}
	info, err := os.Stat(absPath)
	if err != nil {
		return nil, err
	}
	if info.IsDir() {
		absPath = filepath.Join(absPath, ".envrc")
		info, err = os.Stat(absPath)
		if err != nil {
			return nil, err
		}
	}

	content, err := os.ReadFile(absPath)
	if err != nil {
		return nil, err
	}

	return &RC{
		Path:    absPath,
		Dir:     filepath.Dir(absPath),
		IsEnv:   strings.HasSuffix(absPath, ".env"),
		Content: string(content),
	}, nil
}

func AllowHash(path, content string) string {
	h := sha256.New()
	h.Write([]byte(path + "\n" + content))
	return hex.EncodeToString(h.Sum(nil))
}

func DenyHash(path string) string {
	h := sha256.New()
	h.Write([]byte(path + "\n"))
	return hex.EncodeToString(h.Sum(nil))
}

func (rc *RC) Allowed(cfg *Config) AllowedStatus {
	// Whitelist check
	for _, prefix := range cfg.WhitelistPrefix {
		if strings.HasPrefix(rc.Path, prefix) {
			return ALLOWED
		}
	}
	if cfg.WhitelistExact[rc.Path] {
		return ALLOWED
	}

	// Check deny file
	denyKey := DenyHash(rc.Path)
	denyPath := filepath.Join(cfg.DataDir, "deny", denyKey)
	if _, err := os.Stat(denyPath); err == nil {
		return DENIED
	}

	// Check allow file
	allowKey := AllowHash(rc.Path, rc.Content)
	allowPath := filepath.Join(cfg.DataDir, "allow", allowKey)
	if _, err := os.Stat(allowPath); err == nil {
		return ALLOWED
	}

	return NOT_ALLOWED
}

func (rc *RC) Allow(cfg *Config) error {
	allowDir := filepath.Join(cfg.DataDir, "allow")
	denyDir := filepath.Join(cfg.DataDir, "deny")
	os.MkdirAll(allowDir, 0755)
	os.MkdirAll(denyDir, 0755)

	// Remove deny file if exists
	denyKey := DenyHash(rc.Path)
	os.Remove(filepath.Join(denyDir, denyKey))

	// Remove any old allow files for rc.Path
	files, _ := os.ReadDir(allowDir)
	for _, f := range files {
		p := filepath.Join(allowDir, f.Name())
		if data, err := os.ReadFile(p); err == nil {
			if strings.TrimSpace(string(data)) == rc.Path {
				os.Remove(p)
			}
		}
	}

	// Write new allow file
	allowKey := AllowHash(rc.Path, rc.Content)
	allowPath := filepath.Join(allowDir, allowKey)
	return os.WriteFile(allowPath, []byte(rc.Path+"\n"), 0644)
}

func (rc *RC) Block(cfg *Config) error {
	allowDir := filepath.Join(cfg.DataDir, "allow")
