	libDir := filepath.Join(cfg.ConfigDir, "lib")
	if libFiles, err := os.ReadDir(libDir); err == nil {
		for _, lf := range libFiles {
			if strings.HasSuffix(lf.Name(), ".sh") && !lf.IsDir() {
				p := filepath.Join(libDir, lf.Name())
				watches = watches.Add(p)
				script.WriteString(fmt.Sprintf("source %s\n", quoteShell(p)))
			}
		}
	}

