	}

	return newEnv, watches, nil
}

func quoteShell(s string) string {
	return "'" + strings.ReplaceAll(s, "'", "'\\''") + "'"
}

func ParseDump(dumpStr string) (Env, error) {
	if m := len(dumpStr) % 4; m != 0 {
		dumpStr += strings.Repeat("=", 4-m)
	}
