	if err != nil {
		raw, err = base64.StdEncoding.DecodeString(dumpStr)
		if err != nil {
			return nil, err
		}
	}
	r, err := zlib.NewReader(bytes.NewReader(raw))
	if err != nil {
		return nil, err
	}
	defer r.Close()

	var env Env
	if err := json.NewDecoder(r).Decode(&env); err != nil {
		return nil, err
	}
	return env, nil
}

func CreateDump(env Env) (string, error) {
	data, err := json.Marshal(env)
	if err != nil {
		return "", err
	}
	var buf bytes.Buffer
	w := zlib.NewWriter(&buf)
	w.Write(data)
	w.Close()
	return base64.URLEncoding.EncodeToString(buf.Bytes()), nil
}
