package main

import (
	"encoding/json"
	"fmt"
	"os"
	"path/filepath"
	"time"
)

func CmdStatus(cfg *Config, args []string, env Env) error {
	jsonOutput := len(args) > 0 && args[0] == "--json"

	wd, _ := os.Getwd()
	foundRC := FindRC(wd, cfg)

	var loadedRC *RC
	if loadedPath := env["DIRENV_FILE"]; loadedPath != "" {
		if content, err := os.ReadFile(loadedPath); err == nil {
			loadedRC = &RC{
				Path:    loadedPath,
				Dir:     filepath.Dir(loadedPath),
				IsEnv:   filepath.Base(loadedPath) == ".env",
				Content: string(content),
			}
		}
	}

	if jsonOutput {
		type RCStatus struct {
			Allowed AllowedStatus `json:"allowed"`
			Path    string        `json:"path"`
		}
		type StateStatus struct {
			FoundRC  *RCStatus `json:"foundRC"`
			LoadedRC *RCStatus `json:"loadedRC"`
		}
		type ConfigStatus struct {
			ConfigDir string `json:"ConfigDir"`
			SelfPath  string `json:"SelfPath"`
		}
		type StatusJSON struct {
			Config ConfigStatus `json:"config"`
			State  StateStatus  `json:"state"`
		}

		st := StatusJSON{
			Config: ConfigStatus{
				ConfigDir: cfg.ConfigDir,
				SelfPath:  cfg.SelfPath,
			},
		}

		if foundRC != nil {
			st.State.FoundRC = &RCStatus{
				Allowed: foundRC.Allowed(cfg),
				Path:    foundRC.Path,
			}
		}
		if loadedRC != nil {
			st.State.LoadedRC = &RCStatus{
				Allowed: loadedRC.Allowed(cfg),
				Path:    loadedRC.Path,
			}
		}

		data, _ := json.MarshalIndent(st, "", "  ")
		fmt.Println(string(data))
		return nil
	}

	fmt.Printf("direnv exec path %s\n", cfg.SelfPath)
	fmt.Printf("DIRENV_CONFIG %s\n", cfg.ConfigDir)
	fmt.Printf("bash_path %s\n", cfg.BashPath)
	fmt.Printf("disable_stdin %v\n", cfg.DisableStdin)
	fmt.Printf("warn_timeout %s\n", cfg.WarnTimeout)
	fmt.Printf("whitelist.prefix %v\n", cfg.WhitelistPrefix)
	fmt.Printf("whitelist.exact %v\n", cfg.WhitelistExact)

	if loadedRC == nil {
		fmt.Println("No .envrc or .env loaded")
	} else {
		fmt.Printf("Loaded RC path %s\n", loadedRC.Path)
	}

	if foundRC == nil {
		fmt.Println("No .envrc or .env found")
	} else {
		fmt.Printf("Found RC path %s\n", foundRC.Path)

		// Print watches
		rcRel, _ := filepath.Rel(wd, foundRC.Path)
		rcMtime := getMtime(foundRC.Path)
		fmt.Printf("Found watch: \"%s\" - %s\n", rcRel, rcMtime)

		allowKey := AllowHash(foundRC.Path, foundRC.Content)
		allowPath := filepath.Join(cfg.DataDir, "allow", allowKey)
		allowRel, _ := filepath.Rel(wd, allowPath)
		allowMtime := getMtime(allowPath)
		fmt.Printf("Found watch: \"%s\" - %s\n", allowRel, allowMtime)

		denyKey := DenyHash(foundRC.Path)
		denyPath := filepath.Join(cfg.DataDir, "deny", denyKey)
		denyRel, _ := filepath.Rel(wd, denyPath)
		denyMtime := getMtime(denyPath)
		fmt.Printf("Found watch: \"%s\" - %s\n", denyRel, denyMtime)

		allowed := foundRC.Allowed(cfg)
		fmt.Printf("Found RC allowed %d\n", allowed)
		fmt.Printf("Found RC allowPath %s\n", allowPath)
	}

	return nil
}

func getMtime(path string) string {
	info, err := os.Stat(path)
	if err != nil {
		return "1970-01-01T00:00:00Z"
	}
	return info.ModTime().UTC().Format(time.RFC3339)
}
EOF"}

