{"command":"cat << 'EOF' > cmd_allow.go
package main

import (
	"fmt"
	"os"
	"strings"
)

func CmdAllow(cfg *Config, args []string, env Env) error {
	path := "."
	if len(args) > 0 {
		path = args[0]
	}

	rc, err := GetRCAtPath(path, cfg)
	if err != nil {
		cfg.LogError(fmt.Sprintf("%s not found", path))
		return err
	}

	err = rc.Allow(cfg)
	if err != nil {
		return err
	}

	// Also allow required files if DIRENV_REQUIRED is set
	if req := env["DIRENV_REQUIRED"]; req != "" {
		reqPaths := strings.Split(req, ":")
		for _, r := range reqPaths {
			if r == "" {
				continue
			}
			absR := r
			if !strings.HasPrefix(r, "/") {
				absR = fmt.Sprintf("%s/%s", rc.Dir, r)
			}
			if content, err := os.ReadFile(absR); err == nil {
				cfg.Log(fmt.Sprintf("allowing %s", r))
				allowDir := fmt.Sprintf("%s/allow", cfg.DataDir)
				os.MkdirAll(allowDir, 0755)
				allowKey := AllowHash(absR, string(content))
				os.WriteFile(fmt.Sprintf("%s/%s", allowDir, allowKey), []byte(absR+"\n"), 0644)
			}
		}
	}

	return nil
}
EOF"}

