{"command":"cat << 'EOF' > cmd_edit.go
package main

import (
	"fmt"
	"os"
	"os/exec"
	"path/filepath"
)

func CmdEdit(cfg *Config, args []string, env Env) error {
	path := ".envrc"
	if len(args) > 0 {
		path = args[0]
	}

	absPath, err := filepath.Abs(path)
	if err != nil {
		return err
	}

	info, err := os.Stat(absPath)
	if err == nil && info.IsDir() {
		absPath = filepath.Join(absPath, ".envrc")
	}

	var hashBefore string
	if content, err := os.ReadFile(absPath); err == nil {
		hashBefore = AllowHash(absPath, string(content))
	}

	editor := getEditor(env)
	if editor == "" {
		cfg.LogError("No editor found in $EDITOR or $VISUAL")
		return fmt.Errorf("no editor")
	}

	cmd := exec.Command(editor, absPath)
	cmd.Stdin = os.Stdin
	cmd.Stdout = os.Stdout
	cmd.Stderr = os.Stderr

	err = cmd.Run()
	if err != nil {
		cfg.LogError(fmt.Sprintf("%s", err))
		return err
	}

	if newContent, err := os.ReadFile(absPath); err == nil {
		hashAfter := AllowHash(absPath, string(newContent))
		rc := &RC{
