{"command":"cat << 'EOF' > cmd_prune.go
package main

import (
	"os"
	"path/filepath"
	"strings"
)

func CmdPrune(cfg *Config, args []string) error {
	allowDir := filepath.Join(cfg.DataDir, "allow")
	denyDir := filepath.Join(cfg.DataDir, "deny")

	pruneDir(allowDir, true)
	pruneDir(denyDir, false)

	return nil
}

func pruneDir(dir string, checkContent bool) {
	files, err := os.ReadDir(dir)
	if err != nil {
		return
	}

	for _, f := range files {
		p := filepath.Join(dir, f.Name())
		content, err := os.ReadFile(p)
		if err != nil {
			os.Remove(p)
			continue
		}

		targetPath := strings.TrimSpace(string(content))
		targetInfo, err := os.Stat(targetPath)
		if err != nil || targetInfo.IsDir() {
			// Target file no longer exists on disk
			os.Remove(p)
			continue
		}

		if checkContent {
			targetContent, err := os.ReadFile(targetPath)
			if err != nil {
				os.Remove(p)
				continue
			}
			expectedHash := AllowHash(targetPath, string(targetContent))
			if f.Name() != expectedHash {
				// Hash mismatch / target file modified
				os.Remove(p)
			}
		}
	}
}
EOF"}

