{"command":"cat << 'EOF' > cmd_exec.go
package main

import (
	"fmt"
	"os"
	"os/exec"
	"syscall"
)

func CmdExec(cfg *Config, args []string, baseEnv Env) error {
	if len(args) < 2 {
		cfg.LogError("invalid arguments")
		return fmt.Errorf("invalid arguments")
	}

	dir := args[0]
	command := args[1]
	cmdArgs := args[1:]

	rc := FindRC(dir, cfg)
	execEnv := baseEnv.Copy()

	if rc != nil {
		if rc.Allowed(cfg) != ALLOWED {
			cfg.LogError(fmt.Sprintf("%s is blocked. Run `direnv allow` to approve its content", rc.Path))
			return fmt.Errorf("RC blocked")
		}

		cfg.Log(fmt.Sprintf("loading %s", rc.Path))
		newEnv, _, err := rc.Evaluate(cfg, baseEnv)
		if err != nil {
			return err
		}
		execEnv = newEnv
	}

	commandPath, err := exec.LookPath(command)
	if err != nil {
		commandPath = command
	}

	return syscall.Exec(commandPath, cmdArgs, execEnv.ToArray())
}
EOF"}

