{"command":"cat << 'EOF' > cmd_export.go
package main

import (
	"fmt"
	"os"
	"path/filepath"
	"sort"
	"strings"
)

func CmdExport(cfg *Config, args []string, env Env) error {
	if len(args) < 1 {
		cfg.LogError("unknown target shell ''")
		return fmt.Errorf("missing shell")
	}

	shell := args[0]

	oldDiff, _ := ParseEnvDiff(env["DIRENV_DIFF"])
	oldEnv := oldDiff.Undo(env)

	wd, _ := os.Getwd()
	rc := FindRC(wd, cfg)

	oldWatches, _ := ParseWatchList(env["DIRENV_WATCHES"])
	isCurrent, _ := oldWatches.IsCurrent()

	if rc == nil {
		if env["DIRENV_DIR"] != "" || env["DIRENV_DIFF"] != "" {
			cfg.Log("unloading")

			toSet := make(map[string]string)
			toUnset := []string{"DIRENV_DIR", "DIRENV_FILE", "DIRENV_WATCHES", "DIRENV_DIFF", "DIRENV_REQUIRED"}

			// Revert variables in env that came from oldDiff
			for k, vPrev := range oldDiff.Prev {
				if vPrev == nil {
					toUnset = append(toUnset, k)
				} else {
					toSet[k] = *vPrev
				}
			}
			for k := range oldDiff.Next {
				if _, existsInPrev := oldDiff.Prev[k]; !existsInPrev {
					toUnset = append(toUnset, k)
				}
			}

			output, err := FormatExports(shell, toSet, toUnset)
			if err == nil && output != "" {
				fmt.Print(output)
			}
			return nil
		}

		output, err := FormatExports(shell, nil, nil)
		if err == nil && output != "" {
			fmt.Print(output)
		}
		return nil
	}

	allowedStatus := rc.Allowed(cfg)
	if allowedStatus != ALLOWED {
		cfg.LogError(fmt.Sprintf("%s is blocked. Run `direnv allow` to approve its content", rc.Path))

		toSet := make(map[string]string)
		toSet["DIRENV_DIR"] = "-" + rc.Dir
		toSet["DIRENV_FILE"] = rc.Path

		w := NewWatchList().Add(rc.Path)
		allowKey := AllowHash(rc.Path, rc.Content)
		denyKey := DenyHash(rc.Path)
		w = w.Add(filepath.Join(cfg.DataDir, "allow", allowKey))
		w = w.Add(filepath.Join(cfg.DataDir, "deny", denyKey))
		wStr, _ := w.ToBase64()
		toSet["DIRENV_WATCHES"] = wStr

		var toUnset []string
		if env["DIRENV_DIFF"] != "" {
			// Unload previous state
			for k, vPrev := range oldDiff.Prev {
				if vPrev == nil {
					toUnset = append(toUnset, k)
				} else {
					toSet[k] = *vPrev
				}
			}
			for k := range oldDiff.Next {
				if _, existsInPrev := oldDiff.Prev[k]; !existsInPrev {
					toUnset = append(toUnset, k)
				}
			}
			diff := BuildEnvDiff(env, oldEnv)
			diffStr, _ := diff.ToBase64()
			toSet["DIRENV_DIFF"] = diffStr
		} else {
			diff := BuildEnvDiff(env, env)
			diffStr, _ := diff.ToBase64()
			toSet["DIRENV_DIFF"] = diffStr
		}

		out, _ := FormatExports(shell, toSet, toUnset)
		fmt.Print(out)
		return fmt.Errorf("blocked")
	}

	// Check if already loaded and unchanged
	if env["DIRENV_FILE"] == rc.Path && isCurrent {
		return nil
	}

	cfg.Log(fmt.Sprintf("loading %s", rc.Path))

	newEnv, watches, err := rc.Evaluate(cfg, oldEnv)
	if err != nil {
		return err
	}

	diff := BuildEnvDiff(oldEnv, newEnv)
	diffStr, _ := diff.ToBase64()

	allowKey := AllowHash(rc.Path, rc.Content)
	denyKey := DenyHash(rc.Path)
	watches = watches.Add(filepath.Join(cfg.DataDir, "allow", allowKey))
	watches = watches.Add(filepath.Join(cfg.DataDir, "deny", denyKey))
	watchesStr, _ := watches.ToBase64()

	toSet := make(map[string]string)
	var toUnset []string

	toSet["DIRENV_DIR"] = "-" + rc.Dir
	toSet["DIRENV_FILE"] = rc.Path
	toSet["DIRENV_WATCHES"] = watchesStr
	toSet["DIRENV_DIFF"] = diffStr

	var added, modified, removed []string

	for k, vNew := range newEnv {
		if isIgnoredKey(k) {
			continue
		}
		vCurr, existsCurr := env[k]
		if !existsCurr {
			toSet[k] = vNew
			added = append(added, "+"+k)
		} else if vCurr != vNew {
			toSet[k] = vNew
			modified = append(modified, "~"+k)
		}
	}

	for k, vCurr := range env {
		if isIgnoredKey(k) {
			continue
		}
		vNew, existsNew := newEnv[k]
		if !existsNew {
			toUnset = append(toUnset, k)
			removed = append(removed, "-"+k)
		} else if vCurr != vNew && !containsStr(added, "+"+k) && !containsStr(modified, "~"+k) {
			modified = append(modified, "~"+k)
		}
	}

	sort.Strings(added)
	sort.Strings(removed)
	sort.Strings(modified)

	logParts := append(added, removed...)
	logParts = append(logParts, modified...)

	if len(logParts) > 0 && !cfg.HideEnvDiff {
		cfg.Log(fmt.Sprintf("export %s", strings.Join(logParts, " ")))
	}

	out, err := FormatExports(shell, toSet, toUnset)
	if err != nil {
		return err
	}
	fmt.Print(out)

	return nil
}

func containsStr(arr []string, s string) bool {
	for _, item := range arr {
		if item == s {
			return true
		}
	}
	return false
}
EOF"}

