{"command":"cat << 'EOF' > cmd_fetchurl.go
package main

import (
	"crypto/sha256"
	"encoding/base64"
	"encoding/hex"
	"fmt"
	"io"
	"net/http"
	"os"
	"path/filepath"
	"strings"
)

func CmdFetchurl(cfg *Config, args []string) error {
	if len(args) < 1 {
		cfg.LogError("missing URL argument")
		return fmt.Errorf("missing URL argument")
	}

	urlStr := args[0]
	var expectedIntegrity string
	if len(args) > 1 {
		expectedIntegrity = args[1]
	}

	casDir := cfg.CacheDir + "/cas"
	os.MkdirAll(casDir, 0755)

	// If expectedIntegrity provided and file exists in CAS, return path
	if expectedIntegrity != "" {
		expectedHex, err := parseIntegrityHash(expectedIntegrity)
		if err == nil {
			casPath := filepath.Join(casDir, expectedHex)
			if info, err := os.Stat(casPath); err == nil && !info.IsDir() {
				fmt.Println(casPath)
				return nil
			}
		}
	}

	// Fetch URL
	resp, err := http.Get(urlStr)
	if err != nil {
		cfg.LogError(fmt.Sprintf("%s", err))
		return err
	}
	defer resp.Body.Close()

	if resp.StatusCode < 200 || resp.StatusCode >= 300 {
		cfg.LogError(fmt.Sprintf("HTTP error: %s", resp.Status))
		return fmt.Errorf("HTTP error: %s", resp.Status)
	}

	// Download to temp file
	tmpFile, err := os.CreateTemp(casDir, "tmp")
	if err != nil {
		cfg.LogError(fmt.Sprintf("%s", err))
		return err
	}
	tmpPath := tmpFile.Name()
	defer os.Remove(tmpPath)

	h := sha256.New()
	mw := io.MultiWriter(tmpFile, h)

	_, err = io.Copy(mw, resp.Body)
	tmpFile.Close()
	if err != nil {
		cfg.LogError(fmt.Sprintf("%s", err))
		return err
	}

	sum := h.Sum(nil)
	hexHash := hex.EncodeToString(sum)
	sriHash := "sha256-" + base64.StdEncoding.EncodeToString(sum)

	if expectedIntegrity != "" {
		expectedHex, err := parseIntegrityHash(expectedIntegrity)
		if err != nil {
			cfg.LogError(fmt.Sprintf("%s", err))
			return err
		}
		if hexHash != expectedHex {
			cfg.LogError(fmt.Sprintf("hash mismatch. Expected '%s' but got '%s'", expectedIntegrity, sriHash))
			return fmt.Errorf("hash mismatch")
		}

		finalPath := filepath.Join(casDir, hexHash)
		os.Chmod(tmpPath, 0555)
		os.Rename(tmpPath, finalPath)
		fmt.Println(finalPath)
		return nil
	}

	// Move to CAS
	finalPath := filepath.Join(casDir, hexHash)
	os.Chmod(tmpPath, 0555)
	os.Rename(tmpPath, finalPath)

	if isStdoutTTY() {
		fmt.Printf("Found hash: %s\n\n", sriHash)
		fmt.Println("Invoke fetchurl again with the hash as an argument to get the disk location:")
		fmt.Printf("\n  direnv fetchurl \"%s\" \"%s\"\n", urlStr, sriHash)
		fmt.Printf("  #=> %s\n\n", finalPath)
	} else {
		fmt.Println(sriHash)
	}

	return nil
}

func parseIntegrityHash(sri string) (string, error) {
	if !strings.HasPrefix(sri, "sha256-") {
		return "", fmt.Errorf("unsupported hash prefix")
	}
	b64 := sri[7:]
	data, err := base64.StdEncoding.DecodeString(b64)
	if err != nil {
		return "", err
	}
	return hex.EncodeToString(data), nil
}

func isStdoutTTY() bool {
	fileInfo, err := os.Stdout.Stat()
	if err != nil {
		return false
	}
	return (fileInfo.Mode() & os.ModeCharDevice) != 0
}
EOF"}

