{"command":"cat << 'EOF' > cmd_private.go
package main

import (
	"bufio"
	"fmt"
	"io"
	"os"
	"path/filepath"
	"strconv"
	"strings"
)

func CmdApplyDump(cfg *Config, args []string, baseEnv Env) error {
	if len(args) < 1 {
		cfg.LogError("missing dump file")
		return fmt.Errorf("missing dump file")
	}

	content, err := os.ReadFile(args[0])
	if err != nil {
		return err
	}

	targetEnv, err := ParseDump(strings.TrimSpace(string(content)))
	if err != nil {
		return err
	}

	toSet := make(map[string]string)
	var toUnset []string

	for k, vNew := range targetEnv {
		vCurr, exists := baseEnv[k]
		if !exists || vCurr != vNew {
			toSet[k] = vNew
		}
	}

	for k := range baseEnv {
		if _, exists := targetEnv[k]; !exists {
			toUnset = append(toUnset, k)
		}
	}

	out, err := FormatExports("bash", toSet, toUnset)
	if err == nil {
		fmt.Print(out)
	}

	return nil
}

func CmdShowDump(cfg *Config, args []string) error {
	dumpStr := ""
	if len(args) > 0 {
		dumpStr = args[0]
	} else {
		data, _ := io.ReadAll(os.Stdin)
		dumpStr = strings.TrimSpace(string(data))
	}

	env, err := ParseDump(dumpStr)
	if err != nil {
		return err
	}

	data, _ := formatJSON(env, nil)
	fmt.Println(data)
	return nil
}

func CmdCheckRequired(cfg *Config, args []string) error {
	if len(args) < 2 {
		return fmt.Errorf("invalid arguments")
	}

	shell := args[0]
	envrcPath := args[1]
	reqPaths := args[2:]

	envrcDir := filepath.Dir(envrcPath)
	var missing []string

	for _, p := range reqPaths {
		if filepath.IsAbs(p) {
			out, _ := FormatExports(shell, nil, nil)
			fmt.Printf("%slog_error $'require_allowed: path must be relative: %s';\nexit 1;\n", out, p)
			return nil
		}

		absP := filepath.Join(envrcDir, p)
		content, err := os.ReadFile(absP)
		if err != nil {
			missing = append(missing, p)
			continue
		}

		allowKey := AllowHash(absP, string(content))
		allowPath := filepath.Join(cfg.DataDir, "allow", allowKey)
		if _, err := os.Stat(allowPath); err != nil {
			missing = append(missing, p)
		}
	}

	if len(missing) > 0 {
		toSet := map[string]string{
			"DIRENV_REQUIRED": strings.Join(reqPaths, ":"),
		}
		out, _ := FormatExports(shell, toSet, nil)

		var msg string
		if len(missing) == 1 {
			msg = fmt.Sprintf("%s requires approval. Run 'direnv allow' to approve.", missing[0])
		} else {
			msg = fmt.Sprintf("%s require approval. Run 'direnv allow' to approve.", strings.Join(missing[:len(missing)-1], ", ")+" and "+missing[len(missing)-1])
		}

		fmt.Printf("%slog_error $'%s';\nexit 0;\n", out, msg)
		return nil
	}

	return nil
}

func CmdDotenv(cfg *Config, args []string) error {
	shell := "bash"
	dotenvPath := ".env"

	if len(args) == 1 {
		if strings.HasSuffix(args[0], ".env") || strings.Contains(args[0], "/") {
			dotenvPath = args[0]
		} else {
			shell = args[0]
		}
	} else if len(args) >= 2 {
		shell = args[0]
		dotenvPath = args[1]
	}

	data, err := os.ReadFile(dotenvPath)
	if err != nil {
		return err
	}

	envMap := parseDotenvContent(string(data))
	out, err := FormatExports(shell, envMap, nil)
	if err != nil {
		return err
	}
	fmt.Print(out)

	return nil
}

func parseDotenvContent(content string) map[string]string {
	res := make(map[string]string)
	scanner := bufio.NewScanner(strings.NewReader(content))

	for scanner.Scan() {
		line := strings.TrimSpace(scanner.Text())
		if line == "" || strings.HasPrefix(line, "#") {
			continue
		}

		if strings.HasPrefix(line, "export ") {
			line = strings.TrimPrefix(line, "export ")
			line = strings.TrimSpace(line)
		}

		parts := strings.SplitN(line, "=", 2)
		if len(parts) != 2 {
			continue
		}

		key := strings.TrimSpace(parts[0])
