	files, _ := os.ReadDir(allowDir)
	for _, f := range files {
		p := filepath.Join(allowDir, f.Name())
		if data, err := os.ReadFile(p); err == nil {
			if strings.TrimSpace(string(data)) == rc.Path {
				os.Remove(p)
			}
		}
	}

	// Write new allow file
	allowKey := AllowHash(rc.Path, rc.Content)
	allowPath := filepath.Join(allowDir, allowKey)
	return os.WriteFile(allowPath, []byte(rc.Path+"\n"), 0644)
}

func (rc *RC) Block(cfg *Config) error {
	allowDir := filepath.Join(cfg.DataDir, "allow")
	denyDir := filepath.Join(cfg.DataDir, "deny")
	os.MkdirAll(allowDir, 0755)
	os.MkdirAll(denyDir, 0755)

	// Remove old allow files for rc.Path
	files, _ := os.ReadDir(allowDir)
	for _, f := range files {
		p := filepath.Join(allowDir, f.Name())
		if data, err := os.ReadFile(p); err == nil {
			if strings.TrimSpace(string(data)) == rc.Path {
				os.Remove(p)
			}
		}
	}

	// Write deny file
	denyKey := DenyHash(rc.Path)
	denyPath := filepath.Join(denyDir, denyKey)
	return os.WriteFile(denyPath, []byte(rc.Path+"\n"), 0644)
}

func (rc *RC) Evaluate(cfg *Config, baseEnv Env) (Env, WatchList, error) {
	watches := NewWatchList()
	watches = watches.Add(rc.Path)

	// Build bash script
	var script strings.Builder

	strictStr := "set -e\n"
	if cfg.StrictEnv {
		strictStr = "set -euo pipefail\n"
	}
	script.WriteString(strictStr)

	script.WriteString(GetStdlib(cfg.SelfPath))
	script.WriteString("\n")

	// Load direnvrc
	userDirenvrc := filepath.Join(cfg.ConfigDir, "direnvrc")
	if _, err := os.Stat(userDirenvrc); err == nil {
		watches = watches.Add(userDirenvrc)
		script.WriteString(fmt.Sprintf("source %s\n", quoteShell(userDirenvrc)))
	}

	// Load lib/*.sh
	libDir := filepath.Join(cfg.ConfigDir, "lib")
	if libFiles, err := os.ReadDir(libDir); err == nil {
		for _, lf := range libFiles {
			if strings.HasSuffix(lf.Name(), ".sh") && !lf.IsDir() {
				p := filepath.Join(libDir, lf.Name())
				watches = watches.Add(p)
				script.WriteString(fmt.Sprintf("source %s\n", quoteShell(p)))
			}
		}
	}

	// Load target RC
	if rc.IsEnv {
		script.WriteString(fmt.Sprintf("dotenv %s\n", quoteShell(rc.Path)))
	} else {
		script.WriteString(fmt.Sprintf("source %s\n", quoteShell(rc.Path)))
	}

	// Dump command at the end
	script.WriteString(fmt.Sprintf("\n%s dump\n", quoteShell(cfg.SelfPath)))

	// Run bash process
	cmd := exec.Command(cfg.BashPath, "--noprofile", "--norc", "-c", script.String())
	cmd.Dir = rc.Dir

	// Prepare env
	subEnv := baseEnv.Copy()
	subEnv["DIRENV_IN_ENVRC"] = "1"
	cmd.Env = subEnv.ToArray()

	var stdoutBuf, stderrBuf bytes.Buffer
	cmd.Stdout = &stdoutBuf
	cmd.Stderr = &stderrBuf

	if cfg.DisableStdin {
		cmd.Stdin = nil
	} else {
		cmd.Stdin = os.Stdin
	}

	// Handle warn timeout
	done := make(chan error, 1)
	go func() {
		done <- cmd.Run()
	}()

	var err error
	if cfg.WarnTimeout > 0 {
		select {
		case err = <-done:
		case <-time.After(cfg.WarnTimeout):
			cfg.LogError(fmt.Sprintf("([%s export bash]) is taking a while to execute. Use CTRL-C to give up.", cfg.SelfPath))
			err = <-done
		}
	} else {
		err = <-done
	}

	// Forward stderr from bash to stderr
	if stderrBuf.Len() > 0 {
		os.Stderr.Write(stderrBuf.Bytes())
	}

	if err != nil {
		return nil, watches, fmt.Errorf("evaluation failed: %w", err)
	}

	// Parse dump output from stdout
	dumpStr := strings.TrimSpace(stdoutBuf.String())
	lines := strings.Split(dumpStr, "\n")
	lastLine := strings.TrimSpace(lines[len(lines)-1])

	newEnv, err := ParseDump(lastLine)
	if err != nil {
		return nil, watches, fmt.Errorf("failed to parse dump: %w", err)
	}

	return newEnv, watches, nil
}

func quoteShell(s string) string {
	return "'" + strings.ReplaceAll(s, "'", "'\\''") + "'"
}

func ParseDump(dumpStr string) (Env, error) {
	if m := len(dumpStr) % 4; m != 0 {
		dumpStr += strings.Repeat("=", 4-m)
	}
	raw, err := base64.URLEncoding.DecodeString(dumpStr)
	if err != nil {
		raw, err = base64.StdEncoding.DecodeString(dumpStr)
		if err != nil {
			return nil, err
		}
	}
	r, err := zlib.NewReader(bytes.NewReader(raw))
	if err != nil {
		return nil, err
	}
	defer r.Close()

	var env Env
	if err := json.NewDecoder(r).Decode(&env); err != nil {
		return nil, err
	}
	return env, nil
}

func CreateDump(env Env) (string, error) {
	data, err := json.Marshal(env)
	if err != nil {
		return "", err
	}
	var buf bytes.Buffer
	w := zlib.NewWriter(&buf)
	w.Write(data)
	w.Close()
	return base64.URLEncoding.EncodeToString(buf.Bytes()), nil
}
