}

func (e Env) Copy() Env {
	cp := make(Env, len(e))
	for k, v := range e {
		cp[k] = v
	}
	return cp
}

func (e Env) ToArray() []string {
	res := make([]string, 0, len(e))
	for k, v := range e {
		res = append(res, k+"="+v)
	}
	return res
