type EnvDiff struct {
	Prev map[string]*string `json:"p"`
	Next map[string]string  `json:"n"`
}

func NewEnvDiff() *EnvDiff {
	return &EnvDiff{
		Prev: make(map[string]*string),
		Next: make(map[string]string),
	}
}

func BuildEnvDiff(oldEnv, newEnv Env) *EnvDiff {
	diff := NewEnvDiff()

	// Keys in oldEnv
	for k, vOld := range oldEnv {
		if isIgnoredKey(k) {
			continue
		}
		vNew, existsNew := newEnv[k]
		if !existsNew {
			// Removed
			vCopy := vOld
			diff.Prev[k] = &vCopy
		} else if vOld != vNew {
			// Modified
			vCopy := vOld
			diff.Prev[k] = &vCopy
			diff.Next[k] = vNew
		}
	}

	// Keys in newEnv
	for k, vNew := range newEnv {
		if isIgnoredKey(k) {
			continue
		}
		_, existsOld := oldEnv[k]
		if !existsOld {
			// Added
			diff.Prev[k] = nil
			diff.Next[k] = vNew
		}
	}

	return diff
}

func (d *EnvDiff) ToBase64() (string, error) {
	data, err := json.Marshal(d)
	if err != nil {
		return "", err
	}
	var buf bytes.Buffer
	w := zlib.NewWriter(&buf)
	if _, err := w.Write(data); err != nil {
		return "", err
	}
	if err := w.Close(); err != nil {
		return "", err
	}
	return base64.URLEncoding.EncodeToString(buf.Bytes()), nil
}

func ParseEnvDiff(str string) (*EnvDiff, error) {
	if str == "" {
		return NewEnvDiff(), nil
	}
	if m := len(str) % 4; m != 0 {
		str += strings.Repeat("=", 4-m)
	}
	raw, err := base64.URLEncoding.DecodeString(str)
	if err != nil {
		raw, err = base64.StdEncoding.DecodeString(str)
		if err != nil {
			return nil, err
		}
	}
	r, err := zlib.NewReader(bytes.NewReader(raw))
	if err != nil {
		return nil, err
	}
	defer r.Close()

	var diff EnvDiff
	if err := json.NewDecoder(r).Decode(&diff); err != nil {
		return nil, err
	}
	if diff.Prev == nil {
		diff.Prev = make(map[string]*string)
	}
	if diff.Next == nil {
		diff.Next = make(map[string]string)
	}
	return &diff, nil
}

// Undo applies EnvDiff in reverse to currentEnv to recreate oldEnv before direnv changes
func (d *EnvDiff) Undo(currentEnv Env) Env {
	oldEnv := currentEnv.Copy()
	for k, vPrev := range d.Prev {
		if vPrev == nil {
			delete(oldEnv, k)
		} else {
			oldEnv[k] = *vPrev
		}
	}
	return oldEnv
