func CmdApplyDump(cfg *Config, args []string, baseEnv Env) error {
	if len(args) < 1 {
		cfg.LogError("missing dump file")
		return fmt.Errorf("missing dump file")
	}

	content, err := os.ReadFile(args[0])
	if err != nil {
		return err
	}

	targetEnv, err := ParseDump(strings.TrimSpace(string(content)))
	if err != nil {
		return err
	}

	toSet := make(map[string]string)
	var toUnset []string

	for k, vNew := range targetEnv {
		vCurr, exists := baseEnv[k]
		if !exists || vCurr != vNew {
			toSet[k] = vNew
		}
	}

	for k := range baseEnv {
		if _, exists := targetEnv[k]; !exists {
			toUnset = append(toUnset, k)
		}
	}

	out, err := FormatExports("bash", toSet, toUnset)
	if err == nil {
		fmt.Print(out)
	}

	return nil
}

