	wStr, err := watches.ToBase64()
	if err != nil {
		return err
	}

	toSet := map[string]string{
		"DIRENV_WATCHES": wStr,
	}

	out, err := FormatExports(shell, toSet, nil)
	if err != nil {
		return err
	}
	fmt.Print(out)

	return nil
}

func CmdWatchDir(cfg *Config, args []string, baseEnv Env) error {
	if len(args) < 2 {
		return fmt.Errorf("invalid arguments")
	}

	shell := args[0]
	dir := args[1]

	watches, _ := ParseWatchList(baseEnv["DIRENV_WATCHES"])
	watches, err := watches.AddDir(dir)
	if err != nil {
		return err
	}

	wStr, err := watches.ToBase64()
	if err != nil {
		return err
	}

	toSet := map[string]string{
		"DIRENV_WATCHES": wStr,
	}

	out, err := FormatExports(shell, toSet, nil)
	if err != nil {
		return err
	}
	fmt.Print(out)

	return nil
}

func CmdWatchList(cfg *Config, args []string) error {
	shell := "bash"
	if len(args) > 0 {
		shell = args[0]
	}

	scanner := bufio.NewScanner(os.Stdin)
	watches := NewWatchList()

	for scanner.Scan() {
		line := strings.TrimSpace(scanner.Text())
		if line == "" {
			continue
		}
		parts := strings.SplitN(line, " ", 2)
		if len(parts) == 2 {
			mtime, _ := strconv.ParseInt(parts[0], 10, 64)
			path := parts[1]
			absPath, _ := filepath.Abs(path)
			_, err := os.Stat(absPath)
			exists := !os.IsNotExist(err)

			watches = append(watches, WatchItem{
				Path:    absPath,
				ModTime: mtime,
				Exists:  exists,
			})
		}
	}

	wStr, err := watches.ToBase64()
	if err != nil {
		return err
	}

	toSet := map[string]string{
		"DIRENV_WATCHES": wStr,
	}

	out, err := FormatExports(shell, toSet, nil)
	if err != nil {
		return err
	}
	fmt.Print(out)

	return nil
}

func CmdWatchPrint(cfg *Config, args []string, baseEnv Env) error {
	useNull := len(args) > 0 && args[0] == "--null"

	watches, err := ParseWatchList(baseEnv["DIRENV_WATCHES"])
	if err != nil {
		return err
	}

	for _, item := range watches {
		if useNull {
			fmt.Printf("%s\x00", item.Path)
		} else {
			fmt.Println(item.Path)
		}
	}

	return nil
}

func CmdCurrent(cfg *Config, args []string, baseEnv Env) error {
	if len(args) < 1 {
		return fmt.Errorf("invalid arguments")
	}

	path := args[0]
	absPath, _ := filepath.Abs(path)

	watches, err := ParseWatchList(baseEnv["DIRENV_WATCHES"])
	if err != nil {
		cfg.LogError(fmt.Sprintf("File \"%s\" is unknown", path))
		return fmt.Errorf("unknown file")
	}

	for _, item := range watches {
		if item.Path == absPath {
			info, err := os.Stat(absPath)
			exists := !os.IsNotExist(err)
			if exists != item.Exists || (exists && info.ModTime().Unix() != item.ModTime) {
				cfg.LogError(fmt.Sprintf("File \"%s\" has changed", path))
				return fmt.Errorf("file changed")
			}
			return nil
		}
	}

	cfg.LogError(fmt.Sprintf("File \"%s\" is unknown", path))
	return fmt.Errorf("unknown file")
}
EOF"}

