python3 -c '
import subprocess, os, shutil

def run_cmd(binary, cmd, cwd=None, env=None):
    p = subprocess.run(f"{binary} {cmd}", shell=True, capture_output=True, text=True, cwd=cwd, env=env)
    return p.returncode, p.stdout, p.stderr

def test_scenario(name, setup_fn, test_fn):
    test_dir = f"/tmp/test_scenarios/{name}"
    if os.path.exists(test_dir):
        shutil.rmtree(test_dir)
    os.makedirs(test_dir)

    setup_fn(test_dir)
    orig_res = test_fn(test_dir, "/workspace/executable")

    shutil.rmtree(test_dir)
    os.makedirs(test_dir)
    setup_fn(test_dir)
    test_res = test_fn(test_dir, "/workspace/test_executable")

    if orig_res == test_res:
        print(f"PASS: {name}")
    else:
        print(f"FAIL: {name}")
        print("  ORIG:", orig_res)
        print("  TEST:", test_res)

# Scenario 2: export without envrc
def setup_empty(d): pass
def test_export_empty(d, bin_path):
    return run_cmd(bin_path, "export bash", cwd=d)

test_scenario("export_empty", setup_empty, test_export_empty)

# Scenario 3: export blocked envrc
def setup_blocked(d):
    with open(f"{d}/.envrc", "w") as f:
        f.write("export TEST_VAR=123\n")

def test_export_blocked(d, bin_path):
    return run_cmd(bin_path, "export bash", cwd=d)

test_scenario("export_blocked", setup_blocked, test_export_blocked)

# Scenario 4: allow and export
def setup_allow(d):
    with open(f"{d}/.envrc", "w") as f:
        f.write("export TEST_VAR=123\n")

def test_allow_export(d, bin_path):
    rc1, out1, err1 = run_cmd(bin_path, "allow .", cwd=d)
    rc2, out2, err2 = run_cmd(bin_path, "export bash", cwd=d)
    return (rc1, out1, err1, rc2, out2, err2)

test_scenario("allow_export", setup_allow, test_allow_export)

# Scenario 5: dump and show_dump
def setup_dump(d): pass
def test_dump(d, bin_path):
    rc1, out1, err1 = run_cmd(bin_path, "dump", cwd=d)
    dump_str = out1.strip()
    rc2, out2, err2 = run_cmd(bin_path, f"show_dump \"{dump_str}\"", cwd=d)
    return (rc1, err1, rc2, out2, err2)

test_scenario("dump_show_dump", setup_dump, test_dump)
'"}

