{"command":"cat << 'EOF' > env.go
package main

import (
	"bytes"
	"compress/zlib"
	"crypto/rand"
	"encoding/base64"
	"encoding/hex"
	"encoding/json"
	"fmt"
	"os"
	"sort"
	"strings"
)

type Env map[string]string

func GetEnviron() Env {
	env := make(Env)
	for _, item := range os.Environ() {
		parts := strings.SplitN(item, "=", 2)
		if len(parts) == 2 {
			env[parts[0]] = parts[1]
		}
	}
	return env
}

func (e Env) Copy() Env {
	cp := make(Env, len(e))
	for k, v := range e {
		cp[k] = v
	}
	return cp
}

func (e Env) ToArray() []string {
	res := make([]string, 0, len(e))
	for k, v := range e {
		res = append(res, k+"="+v)
	}
	return res
}

type EnvDiff struct {
	Prev map[string]*string `json:"p"`
	Next map[string]string  `json:"n"`
}

func NewEnvDiff() *EnvDiff {
	return &EnvDiff{
		Prev: make(map[string]*string),
		Next: make(map[string]string),
	}
}

func BuildEnvDiff(oldEnv, newEnv Env) *EnvDiff {
	diff := NewEnvDiff()

	// Keys in oldEnv
	for k, vOld := range oldEnv {
		if isIgnoredKey(k) {
			continue
		}
		vNew, existsNew := newEnv[k]
		if !existsNew {
			// Removed
			vCopy := vOld
			diff.Prev[k] = &vCopy
		} else if vOld != vNew {
			// Modified
			vCopy := vOld
			diff.Prev[k] = &vCopy
			diff.Next[k] = vNew
		}
	}

	// Keys in newEnv
	for k, vNew := range newEnv {
		if isIgnoredKey(k) {
			continue
		}
		_, existsOld := oldEnv[k]
		if !existsOld {
			// Added
			diff.Next[k] = vNew
		}
	}

	return diff
}

func (d *EnvDiff) ToBase64() (string, error) {
	data, err := json.Marshal(d)
	if err != nil {
		return "", err
	}
	var buf bytes.Buffer
	w := zlib.NewWriter(&buf)
	if _, err := w.Write(data); err != nil {
		return "", err
	}
	if err := w.Close(); err != nil {
		return "", err
	}
	return base64.URLEncoding.EncodeToString(buf.Bytes()), nil
}

func ParseEnvDiff(str string) (*EnvDiff, error) {
	if str == "" {
		return NewEnvDiff(), nil
	}
	if m := len(str) % 4; m != 0 {
		str += strings.Repeat("=", 4-m)
	}
	raw, err := base64.URLEncoding.DecodeString(str)
	if err != nil {
		raw, err = base64.StdEncoding.DecodeString(str)
		if err != nil {
			return nil, err
		}
	}
	r, err := zlib.NewReader(bytes.NewReader(raw))
	if err != nil {
		return nil, err
	}
	defer r.Close()

	var diff EnvDiff
	if err := json.NewDecoder(r).Decode(&diff); err != nil {
		return nil, err
	}
	if diff.Prev == nil {
