)

type Env map[string]string

func GetEnviron() Env {
	env := make(Env)
	for _, item := range os.Environ() {
		parts := strings.SplitN(item, "=", 2)
		if len(parts) == 2 {
			env[parts[0]] = parts[1]
		}
	}
	return env
}

func (e Env) Copy() Env {
	cp := make(Env, len(e))
	for k, v := range e {
		cp[k] = v
	}
	return cp
}

func (e Env) ToArray() []string {
	res := make([]string, 0, len(e))
	for k, v := range e {
		res = append(res, k+"="+v)
	}
	return res
}

type EnvDiff struct {
	Prev map[string]*string `json:"p"`
	Next map[string]string  `json:"n"`
}

func NewEnvDiff() *EnvDiff {
	return &EnvDiff{
		Prev: make(map[string]*string),
		Next: make(map[string]string),
	}
}

func BuildEnvDiff(oldEnv, newEnv Env) *EnvDiff {
	diff := NewEnvDiff()

	// Keys in oldEnv
	for k, vOld := range oldEnv {
		if isIgnoredKey(k) {
			continue
		}
		vNew, existsNew := newEnv[k]
		if !existsNew {
			// Removed
			vCopy := vOld
			diff.Prev[k] = &vCopy
		} else if vOld != vNew {
			// Modified
			vCopy := vOld
			diff.Prev[k] = &vCopy
			diff.Next[k] = vNew
		}
	}

	// Keys in newEnv
	for k, vNew := range newEnv {
		if isIgnoredKey(k) {
			continue
		}
		_, existsOld := oldEnv[k]
		if !existsOld {
			// Added
			diff.Next[k] = vNew
		}
	}

	return diff
}

func (d *EnvDiff) ToBase64() (string, error) {
	data, err := json.Marshal(d)
	if err != nil {
		return "", err
	}
	var buf bytes.Buffer
	w := zlib.NewWriter(&buf)
	if _, err := w.Write(data); err != nil {
		return "", err
	}
	if err := w.Close(); err != nil {
		return "", err
	}
	return base64.URLEncoding.EncodeToString(buf.Bytes()), nil
}

func ParseEnvDiff(str string) (*EnvDiff, error) {
	if str == "" {
		return NewEnvDiff(), nil
	}
	if m := len(str) % 4; m != 0 {
		str += strings.Repeat("=", 4-m)
	}
	raw, err := base64.URLEncoding.DecodeString(str)
	if err != nil {
		raw, err = base64.StdEncoding.DecodeString(str)
		if err != nil {
			return nil, err
		}
	}
	r, err := zlib.NewReader(bytes.NewReader(raw))
	if err != nil {
		return nil, err
	}
	defer r.Close()

	var diff EnvDiff
	if err := json.NewDecoder(r).Decode(&diff); err != nil {
		return nil, err
	}
	if diff.Prev == nil {
		diff.Prev = make(map[string]*string)
	}
	if diff.Next == nil {
		diff.Next = make(map[string]string)
	}
	return &diff, nil
}

// Undo applies EnvDiff in reverse to currentEnv to recreate oldEnv before direnv changes
func (d *EnvDiff) Undo(currentEnv Env) Env {
	oldEnv := currentEnv.Copy()
	for k, vPrev := range d.Prev {
		if vPrev == nil {
			delete(oldEnv, k)
		} else {
			oldEnv[k] = *vPrev
		}
	}
	for k := range d.Next {
		if _, existsInPrev := d.Prev[k]; !existsInPrev {
			delete(oldEnv, k)
		}
	}
	return oldEnv
}

func isIgnoredKey(k string) bool {
	switch k {
	case "_",
		"DIRENV_IN_ENVRC",
		"DIRENV_DIFF",
		"COMP_WORDBREAKS",
		"PS1",
		"SHLVL",
		"SHELLOPTS",
		"BASH_ARGC",
		"BASH_ARGV",
		"BASH_LINENO",
		"BASH_SOURCE",
		"BASH_VERSINFO",
		"PIPESTATUS",
		"PWD",
		"OLDPWD":
		return true
	}
	return false
}

// FormatExports formats environment changes for a target shell.
func FormatExports(targetShell string, toSet map[string]string, toUnset []string) (string, error) {
	targetShell = strings.ToLower(targetShell)

	switch targetShell {
	case "bash", "zsh":
		return formatBashZsh(toSet, toUnset), nil
	case "fish":
		return formatFish(toSet, toUnset), nil
	case "tcsh":
		return formatTcsh(toSet, toUnset), nil
	case "elvish":
		return formatElvish(toSet, toUnset), nil
	case "pwsh":
		return formatPwsh(toSet, toUnset), nil
	case "murex":
		return formatMurex(toSet, toUnset), nil
	case "json":
		return formatJSON(toSet, toUnset), nil
	case "vim":
		return formatVim(toSet, toUnset), nil
	case "gha":
		return formatGHA(toSet, toUnset), nil
	case "gzenv":
		return formatGzenv(toSet, toUnset), nil
	case "systemd":
		return formatSystemd(toSet, toUnset), nil
	default:
		return "", fmt.Errorf("unknown target shell '%s'", targetShell)
	}
}

func formatBashZsh(toSet map[string]string, toUnset []string) string {
	var sb strings.Builder

	allKeys := make([]string, 0, len(toSet)+len(toUnset))
	for k := range toSet {
		allKeys = append(allKeys, k)
	}
	for _, k := range toUnset {
		allKeys = append(allKeys, k)
	}
	sort.Strings(allKeys)

	unsetMap := make(map[string]bool)
	for _, k := range toUnset {
		unsetMap[k] = true
	}

	for _, k := range allKeys {
		if unsetMap[k] {
			sb.WriteString(fmt.Sprintf("unset %s;", k))
		} else {
			val := toSet[k]
			sb.WriteString(fmt.Sprintf("export %s=$'%s';", k, escapeBashDollar(val)))
		}
	}
	return sb.String()
}

func escapeBashDollar(s string) string {
	s = strings.ReplaceAll(s, "\\", "\\\\")
	s = strings.ReplaceAll(s, "'", "\\'")
	s = strings.ReplaceAll(s, "\n", "\\n")
	s = strings.ReplaceAll(s, "\r", "\\r")
	s = strings.ReplaceAll(s, "\t", "\\t")
	return s
}

func formatFish(toSet map[string]string, toUnset []string) string {
