}

func formatGHA(toSet map[string]string, toUnset []string) string {
	var sb strings.Builder

	allKeys := make([]string, 0, len(toSet))
	for k := range toSet {
		allKeys = append(allKeys, k)
	}
	sort.Strings(allKeys)

	for _, k := range allKeys {
		val := toSet[k]
		delimiter := "ghadelimiter_" + randomUUID()
		sb.WriteString(fmt.Sprintf("%s<<%s\n%s\n%s\n", k, delimiter, val, delimiter))
	}
	return sb.String()
}

func formatGzenv(toSet map[string]string, toUnset []string) string {
	m := make(map[string]string)
	for k, v := range toSet {
		m[k] = v
	}
	data, _ := json.Marshal(m)
	var buf bytes.Buffer
	w := zlib.NewWriter(&buf)
	w.Write(data)
	w.Close()
	return base64.URLEncoding.EncodeToString(buf.Bytes())
}

func formatSystemd(toSet map[string]string, toUnset []string) string {
	var sb strings.Builder

	allKeys := make([]string, 0, len(toSet))
	for k := range toSet {
		allKeys = append(allKeys, k)
	}
	sort.Strings(allKeys)

	for _, k := range allKeys {
		val := toSet[k]
		sb.WriteString(fmt.Sprintf("%s=%s\n", k, escapeSystemd(val)))
	}
	return sb.String()
}

func escapeSystemd(s string) string {
	s = strings.ReplaceAll(s, "\\", "\\\\")
	s = strings.ReplaceAll(s, "\"", "\\\"")
	s = strings.ReplaceAll(s, "\n", "\\n")
	return "\"" + s + "\""
}

func randomUUID() string {
	b := make([]byte, 16)
	_, err := rand.Read(b)
	if err != nil {
		return "1234567890abcdef1234567890abcdef"
	}
	return hex.EncodeToString(b)
}
