		newEnvBlocked := oldEnv.Copy()
		newEnvBlocked["DIRENV_DIR"] = "-" + rc.Dir
		newEnvBlocked["DIRENV_FILE"] = rc.Path
		newEnvBlocked["DIRENV_WATCHES"] = wStr

		diff := BuildEnvDiff(oldEnv, newEnvBlocked)
		diffStr, _ := diff.ToBase64()
		toSet["DIRENV_DIFF"] = diffStr

		if env["DIRENV_DIFF"] != "" {
			for k, vPrev := range oldDiff.Prev {
				if vPrev == nil {
					toUnset = append(toUnset, k)
				} else {
					toSet[k] = *vPrev
				}
			}
			for k := range oldDiff.Next {
				if _, existsInPrev := oldDiff.Prev[k]; !existsInPrev {
					toUnset = append(toUnset, k)
				}
			}
		}

		out, _ := FormatExports(shell, toSet, toUnset)
		fmt.Print(out)
		return fmt.Errorf("blocked")
	}

	// Check if already loaded and unchanged
	if env["DIRENV_FILE"] == rc.Path && isCurrent {
		return nil
	}

	cfg.Log(fmt.Sprintf("loading %s", rc.Path))

	newEnv, watches, err := rc.Evaluate(cfg, oldEnv)
	if err != nil {
		return err
	}

	allowKey := AllowHash(rc.Path, rc.Content)
	denyKey := DenyHash(rc.Path)
	watches = watches.Add(filepath.Join(cfg.DataDir, "allow", allowKey))
	watches = watches.Add(filepath.Join(cfg.DataDir, "deny", denyKey))
	watchesStr, _ := watches.ToBase64()

	newEnv["DIRENV_DIR"] = "-" + rc.Dir
	newEnv["DIRENV_FILE"] = rc.Path
	newEnv["DIRENV_WATCHES"] = watchesStr

	diff := BuildEnvDiff(oldEnv, newEnv)
	diffStr, _ := diff.ToBase64()
	newEnv["DIRENV_DIFF"] = diffStr

	toSet := make(map[string]string)
